import{_ as o,l as i,o as e,c as l,v as t,p as d,x as r,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"填充预言机","description":"","frontmatter":{"title":"填充预言机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/padding-oracle.md","filePath":"cs/padding-oracle.md","lastUpdated":1789023840000}'),h={name:"cs/padding-oracle.md"};function E(A,a,C,u,_,m){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="填充预言机" tabindex="-1">填充预言机 <a class="header-anchor" href="#填充预言机" aria-label="Permalink to &quot;填充预言机&quot;">​</a></h1><div class="epigraph"><p>CBC 解密后若把「填充合不合法」与「MAC 失败」用可区分的方式告诉外界，主动敌手就能把解密器当成一位一位的预言。防御是 AEAD，以及失败不可区分。</p><footer>—— Vaudenay, Security Flaws Induced by CBC Padding, EUROCRYPT 2002；对照 TLS 对填充与 MAC 的历史修补</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/nonce-misuse">nonce 误用</a>是状态合同。缺口是<strong>错误通道</strong>：即使 nonce 唯一，分组密码的填充校验若变成可观测谓词，Dolev–Yao 的理想锁也不成立。本课讲机制与防御，不给可复现的明文恢复步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PKCS#7 一类填充让明文长度凑整。CBC 解密后检查填充。若攻击者改密文块并得知「填充错还是 MAC 错」，就得到一位预言。历史 TLS 与若干框架因此换套件。缺口是：完整性必须在解密前或与解密原子地验；错误不可区分。</p><h3 id="不是作业题" tabindex="-1">不是作业题 <a class="header-anchor" href="#不是作业题" aria-label="Permalink to &quot;不是作业题&quot;">​</a></h3><p>课程禁止把预言机利用写成实验指导。需要的只是：可区分的失败 = 额外的解密预言；关掉它。</p><p><span class="marginnote">Vaudenay 2002。Lucky Thirteen 一类是计时变体，同属错误/时间通道。TLS 1.3 删除 CBC 套件，从根上换 AEAD。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述 Encrypt-then-MAC 与 AEAD 如何让「密文未认证则不解密」。统一错误码与常数时间失败路径。旧栈若必须留 CBC，也不可把填充错误单独抛出。</p>',12)),(e(),d(p,null,{default:r(()=>[c(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CT%5B%22%E6%94%B9%E8%BF%87%E7%9A%84%E5%AF%86%E6%96%87%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E5%AF%86%E5%B9%B6%E6%9F%A5%E5%A1%AB%E5%85%85%22%5D%0A%20%20DEC%20--%3E%20E1%5B%22%E5%A1%AB%E5%85%85%E9%94%99%22%5D%0A%20%20DEC%20--%3E%20E2%5B%22MAC%20%E9%94%99%22%5D%0A%20%20E1%20--%3E%20ORACLE%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%88%99%E6%88%90%E9%A2%84%E8%A8%80%22%5D%0A%20%20E2%20--%3E%20ORACLE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主动敌手的能力包括改字节并看反应。规格若把内部校验暴露成不同 HTTP 状态、不同耗时、不同日志，就等于提供 $ \\mathrm{Dec} $ 的部分信息。这与 nonce 复用正交：即使每条消息 nonce 都新，错误通道仍在。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析某 CVE 的报文。哈希结构下一课：消息摘要如何迭代，与填充预言无关，但同属「把可变长输入收成固定对象」的进阶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>nonce 合同之外，错误信息也是通道。</li><li>CBC 填充校验可被当成预言；不要区分失败原因。</li><li>AEAD 与 Encrypt-then-MAC 从结构上关掉。</li><li>下一课 Merkle–Damgård：哈希的迭代结构。</li><li>出处：Vaudenay, 2002；Krawczyk 对 MAC-then-encrypt 的讨论；RFC 8446 删除 CBC。</li></ul>',8))])}const B=o(h,[["render",E]]);export{f as __pageData,B as default};
